(function(){try{var theme=localStorage.getItem('lh-theme');if(theme!=='dark'&&theme!=='light')theme=matchMedia('(prefers-color-scheme: light)').matches?'light':'dark';document.documentElement.dataset.theme=theme;if(localStorage.getItem('lh-large-text')==='true')document.documentElement.classList.add('large-text');if(localStorage.getItem('lh-pause-motion')==='true')document.documentElement.classList.add('motion-off');if(localStorage.getItem('lh-high-contrast')==='true')document.documentElement.classList.add('high-contrast');}catch(e){}}());